// Sistema de límites de imágenes
let imageUsage = { generated: 0, limit: 2 }; // Plan gratuito: 2 imágenes en 7 días

// Usuarios con acceso especial (admin/testing)
const ADMIN_EMAILS = [
  'alejandro.gonzalez.ads@gmail.com',
  'alejandro@acuarius.app',
  'admin@acuarius.app',
  'test@acuarius.app'
];

function isAdminUser() {
  if (!clerkInstance?.user?.primaryEmailAddress?.emailAddress) return false;
  return ADMIN_EMAILS.includes(clerkInstance.user.primaryEmailAddress.emailAddress.toLowerCase());
}

// Funciones de límites
function loadImageUsage() {
  if (userPlan === 'agency' || isAdminUser()) {
    imageUsage = { generated: 0, limit: 9999 }; // Ilimitado para Agency y Admin
    return;
  }
  if (userPlan === 'pro') {
    // Pro: 60/mes — reset mensual
    try {
      const saved = localStorage.getItem('acuarius_image_usage');
      if (saved) {
        const data = JSON.parse(saved);
        const now = Date.now();
        const oneMonth = 30 * 24 * 60 * 60 * 1000;
        if (now - (data.timestamp || 0) > oneMonth) {
          imageUsage = { generated: 0, limit: 60, timestamp: now };
          saveImageUsage();
        } else {
          imageUsage = { generated: data.generated || 0, limit: 60, timestamp: data.timestamp };
        }
      } else {
        imageUsage = { generated: 0, limit: 60, timestamp: Date.now() };
        saveImageUsage();
      }
    } catch (e) {
      imageUsage = { generated: 0, limit: 60, timestamp: Date.now() };
    }
    return;
  }
  // Free: 3 imágenes
  try {
    const saved = localStorage.getItem('acuarius_image_usage');
    if (saved) {
      const data = JSON.parse(saved);
      imageUsage = { generated: data.generated || 0, limit: 3 };
    } else {
      imageUsage = { generated: 0, limit: 3 };
      saveImageUsage();
    }
  } catch (e) {
    imageUsage = { generated: 0, limit: 3 };
  }
}

function saveImageUsage() {
  try {
    localStorage.setItem('acuarius_image_usage', JSON.stringify(imageUsage));
  } catch (e) {}
}

function canGenerateImage() {
  loadImageUsage();
  return isAdminUser() || imageUsage.generated < imageUsage.limit;
}

function incrementImageUsage() {
  if (!isAdminUser() && userPlan !== 'agency') {
    imageUsage.generated++;
    saveImageUsage();
  }
}

// Contador mensual de mensajes para plan Free (50/mes)
function getMsgUsage() {
  if (userPlan !== 'free' || isAdminUser()) return { count: 0, limit: 9999 };
  try {
    const data = JSON.parse(localStorage.getItem('acuarius_msg_usage') || '{}');
    const monthKey = new Date().toISOString().slice(0, 7);
    if (data.month !== monthKey) return { count: 0, limit: 50, month: monthKey };
    return { count: data.count || 0, limit: 50, month: data.month };
  } catch { return { count: 0, limit: 50, month: '' }; }
}

function canSendFreeMsg() {
  if (userPlan !== 'free' || isAdminUser()) return true;
  const { count, limit } = getMsgUsage();
  return count < limit;
}

function incrementMsgUsage() {
  if (userPlan !== 'free' || isAdminUser()) return;
  try {
    const usage = getMsgUsage();
    const monthKey = new Date().toISOString().slice(0, 7);
    localStorage.setItem('acuarius_msg_usage', JSON.stringify({ count: (usage.count || 0) + 1, month: monthKey }));
  } catch {}
}

