// ── MÓDULO LEADS / CRM ────────────────────────────────────────────────────────
let crmStages = [];
let crmLeads = [];
let crmView = 'kanban'; // 'kanban' | 'list'
let crmEditingId = null;
let crmDetailLead = null;
let crmInited = false;
let crmSearchQuery = '';
let crmFilterSource = '';
let crmActivityType = 'nota';
let crmQuickFilter = '';

async function crmInit() {
  if (crmInited) { crmRender(); return; }
  crmInited = true;
  await crmLoadStages();
  await crmLoadLeads();
  crmUpdateSidebarCount();
}

async function crmLoadStages() {
  try {
    // Stages are global per user (not per client)
    const res = await fetch('/api/pipeline-stages', { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    crmStages = data.stages || [];
    crmPopulateStageSelects();
  } catch(e) {
    console.error('crmLoadStages', e);
  }
}

async function crmLoadLeads() {
  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    const qs = clientId ? `?client_id=${encodeURIComponent(clientId)}` : '';
    const res = await fetch(`/api/leads${qs}`, { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    crmLeads = data.leads || [];
    crmRender();
  } catch(e) {
    console.error('crmLoadLeads', e);
  }
}

function crmPopulateStageSelects() {
  ['crm-f-stage', 'crm-d-stage'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = crmStages.map(s => `<option value="${esc(s.key)}">${esc(s.label)}</option>`).join('');
  });
}

function crmSetView(v) {
  crmView = v;
  document.getElementById('crm-btn-kanban').classList.toggle('active', v === 'kanban');
  document.getElementById('crm-btn-list').classList.toggle('active', v === 'list');
  document.getElementById('crm-kanban').style.display = v === 'kanban' ? 'flex' : 'none';
  document.getElementById('crm-list-view').style.display = v === 'list' ? 'block' : 'none';
  crmRender();
}

function crmRender() {
  if (crmView === 'kanban') crmRenderKanban();
  else crmRenderList();
  crmUpdateClientTag();
  crmUpdateSidebarCount();
}

// ── Etiquetas del CRM ─────────────────────────────────────────────────────────
// Catálogo en lead_tags (colores, tipo auto/manual); las etiquetas de cada lead
// viven en leads.tags. Misma normalización y paleta que el backend, así el
// color es idéntico aunque la etiqueta aún no esté en el catálogo.
let crmTags = [];
let crmFilterTags = [];
const TAG_PALETTE = ['#3B82F6','#10B981','#F59E0B','#8B5CF6','#EC4899','#14B8A6','#EF4444','#6366F1','#84CC16','#F97316'];

function normalizeTag(name) {
  return String(name || '').trim().toLowerCase().replace(/\s+/g, ' ').slice(0, 30);
}

function tagColor(name) {
  const cat = crmTags.find(t => t.name === name);
  if (cat && cat.color) return cat.color;
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  return TAG_PALETTE[h % TAG_PALETTE.length];
}

function tagIsAuto(name) {
  const cat = crmTags.find(t => t.name === name);
  return cat ? cat.kind === 'auto' : false;
}

function tagChipHtml(name, removable) {
  const c = tagColor(name);
  return '<span class="tag-chip" style="background:' + c + '1A;color:' + c + '" title="' + (tagIsAuto(name) ? 'Etiqueta automática' : 'Etiqueta') + '">' +
    (tagIsAuto(name) ? '⚡' : '') + esc(name) +
    (removable ? '<button class="tag-chip-x" onclick="event.stopPropagation();crmDetailRemoveTag(\'' + esc(name) + '\')" title="Quitar">✕</button>' : '') +
    '</span>';
}

async function crmLoadTags() {
  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    const qs = clientId ? '?client_id=' + encodeURIComponent(clientId) : '';
    const res = await fetch('/api/lead-tags' + qs, { headers: await getAuthHeaders() });
    crmTags = (await res.json()).tags || [];
  } catch { crmTags = []; }
  crmRenderTagFilter();
}

async function crmEnsureTag(name) {
  const n = normalizeTag(name);
  if (n.length < 2) return null;
  if (crmTags.find(t => t.name === n)) return n;
  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    const qs = clientId ? '?client_id=' + encodeURIComponent(clientId) : '';
    const res = await fetch('/api/lead-tags' + qs, { method: 'POST', headers: await getAuthHeaders(), body: JSON.stringify({ name: n }) });
    const d = await res.json();
    if (d.tag && !crmTags.find(t => t.name === d.tag.name)) crmTags.push(d.tag);
  } catch {}
  return n;
}

// Filtro por etiquetas: pills clicables junto a los quick filters (AND)
function crmRenderTagFilter() {
  const wrap = document.getElementById('crm-tag-filter');
  if (!wrap) return;
  // Etiquetas en uso (catálogo + las que existan en leads aunque falten en catálogo)
  const inUse = new Set(crmTags.map(t => t.name));
  (crmLeads || []).forEach(l => (l.tags || []).forEach(t => inUse.add(t)));
  const names = [...inUse].sort();
  if (!names.length) { wrap.innerHTML = ''; return; }
  wrap.innerHTML = names.slice(0, 14).map(n => {
    const c = tagColor(n);
    const on = crmFilterTags.includes(n);
    return '<button class="tag-chip tag-filter-chip' + (on ? ' on' : '') + '" style="' +
      (on ? 'background:' + c + ';color:#fff' : 'background:' + c + '1A;color:' + c) +
      '" onclick="crmToggleTagFilter(\'' + esc(n) + '\')">' + esc(n) + '</button>';
  }).join('') + (crmFilterTags.length ? '<button class="tag-filter-clear" onclick="crmFilterTags=[];crmRenderTagFilter();crmRender();crmUpdateLeadsStats()">limpiar</button>' : '');
}

function crmToggleTagFilter(name) {
  const i = crmFilterTags.indexOf(name);
  if (i >= 0) crmFilterTags.splice(i, 1); else crmFilterTags.push(name);
  crmRenderTagFilter();
  crmRender();
  crmUpdateLeadsStats();
}

function crmGetFilteredLeads() {
  let leads = [...crmLeads];
  if (crmSearchQuery) {
    const q = crmSearchQuery.toLowerCase();
    leads = leads.filter(l =>
      (l.name || '').toLowerCase().includes(q) ||
      (l.company || '').toLowerCase().includes(q) ||
      (l.email || '').toLowerCase().includes(q) ||
      (l.phone || '').includes(q)
    );
  }
  if (crmFilterSource) leads = leads.filter(l => l.source === crmFilterSource);
  if (crmFilterTags.length) leads = leads.filter(l => crmFilterTags.every(t => (l.tags || []).includes(t)));
  if (crmQuickFilter === 'inactive') {
    const now = Date.now();
    leads = leads.filter(l => {
      if (l.stage === 'ganado' || l.stage === 'perdido') return false;
      const lastActive = l.updated_at ? new Date(l.updated_at).getTime() : new Date(l.created_at || 0).getTime();
      return Math.floor((now - lastActive) / 86400000) >= 7;
    });
  } else if (crmQuickFilter === 'score') {
    leads = leads.filter(l => l.custom_fields && Number(l.custom_fields.score) >= 7);
  } else if (crmQuickFilter === 'value') {
    leads = leads.filter(l => Number(l.value) > 0);
  } else if (crmQuickFilter === 'mine') {
    const myId = (typeof clerkInstance !== 'undefined' && clerkInstance?.user?.id) || '';
    leads = leads.filter(l => l.assigned_to === myId);
  }
  return leads;
}

function crmToggleQuickFilter(type) {
  crmQuickFilter = crmQuickFilter === type ? '' : type;
  document.querySelectorAll('.crm-qf-pill').forEach(p => p.classList.remove('active'));
  if (crmQuickFilter) {
    const btn = document.getElementById('crm-qf-' + crmQuickFilter);
    if (btn) btn.classList.add('active');
  }
  crmRender();
  crmUpdateLeadsStats();
}

function crmExportCSV() {
  if (!crmLeads.length) { alert('No hay leads para exportar.'); return; }
  const headers = ['Nombre','Email','Teléfono','Empresa','Etapa','Fuente','Valor','Tags','Notas','Fecha creación'];
  const rows = crmGetFilteredLeads().map(l => [
    l.name || '',
    l.email || '',
    l.phone || '',
    l.company || '',
    l.stage || '',
    l.source || '',
    l.value || '',
    (l.tags || []).join('; '),
    (l.notes || '').replace(/\n/g,' '),
    l.created_at ? new Date(l.created_at).toLocaleDateString('es-CO') : '',
  ].map(v => '"' + String(v).replace(/"/g, '""') + '"').join(','));
  const csv = [headers.join(','), ...rows].join('\n');
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'leads_acuarius_' + new Date().toISOString().slice(0,10) + '.csv';
  a.click(); URL.revokeObjectURL(url);
}

function crmSetSearch(q) {
  crmSearchQuery = q;
  crmRender();
  crmUpdateLeadsStats();
}

function crmSetFilter(key, val) {
  if (key === 'source') crmFilterSource = val;
  crmRender();
  crmUpdateLeadsStats();
}

function crmUpdateLeadsStats() {
  const el = document.getElementById('crm-leads-stats');
  if (!el) return;
  const filtered = crmGetFilteredLeads();
  const total = crmLeads.length;
  if (filtered.length === total) {
    el.textContent = total + ' leads';
  } else {
    el.textContent = filtered.length + ' de ' + total;
  }
}

function crmRenderKanban() {
  const container = document.getElementById('crm-kanban');
  if (!container) return;
  const filtered = crmGetFilteredLeads();

  // Pipeline total
  const totalValue = filtered.reduce((s, l) => s + (Number(l.value) || 0), 0);
  let totalEl = document.getElementById('crm-pipeline-total');
  if (!totalEl) {
    totalEl = document.createElement('div');
    totalEl.id = 'crm-pipeline-total';
    totalEl.className = 'crm-pipeline-total';
    container.parentNode.insertBefore(totalEl, container);
  }
  totalEl.style.display = totalValue > 0 ? 'flex' : 'none';
  if (totalValue > 0) totalEl.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg> Pipeline total: $' + totalValue.toLocaleString('es-CO');

  container.innerHTML = '';
  const now = Date.now();
  crmStages.forEach(stage => {
    const leads = filtered.filter(l => l.stage === stage.key);
    const stageValue = leads.reduce((s, l) => s + (Number(l.value) || 0), 0);
    const col = document.createElement('div');
    col.className = 'crm-col';
    col.innerHTML = '<div class="crm-col-head" style="border-left-color:' + esc(stage.color) + '">' +
      '<div class="crm-col-label">' + esc(stage.label) + '</div>' +
      '<div style="display:flex;align-items:center;gap:8px">' +
      (stageValue > 0 ? '<div class="crm-col-value">$' + stageValue.toLocaleString('es-CO') + '</div>' : '') +
      '<div class="crm-col-count">' + leads.length + '</div>' +
      '</div></div>' +
      '<div class="crm-col-body" id="crm-col-' + esc(stage.key) + '" data-stage="' + esc(stage.key) + '">' +
      (leads.length === 0 ? '<div style="font-size:11px;color:var(--muted2);text-align:center;padding:20px 0">Sin leads</div>' : leads.map(l => crmCardHTML(l, now)).join('')) +
      '<button class="crm-add-card" onclick="crmOpenModal(\'' + esc(stage.key) + '\')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg> Agregar</button></div>';
    container.appendChild(col);
    crmSetupDrop(col.querySelector('.crm-col-body'), stage.key);
  });
  container.querySelectorAll('.crm-card').forEach(card => {
    card.draggable = true;
    card.addEventListener('dragstart', e => {
      e.dataTransfer.setData('text/plain', card.dataset.id);
      card.classList.add('dragging');
    });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
    card.addEventListener('click', () => crmOpenDetail(card.dataset.id));
  });
  crmUpdateLeadsStats();
}

function crmCardHTML(lead, now) {
  const sourceLabels = { manual: 'Manual', meta_ads: 'Meta Ads', google_ads: 'Google Ads', organico: 'Orgánico', referido: 'Referido', web: 'Web' };
  const ts = now || Date.now();
  const lastActive = lead.updated_at ? new Date(lead.updated_at).getTime() : new Date(lead.created_at || 0).getTime();
  const daysSince = Math.floor((ts - lastActive) / 86400000);
  const showInactive = daysSince >= 7 && lead.stage !== 'ganado' && lead.stage !== 'perdido';
  const score = lead.custom_fields && lead.custom_fields.score ? Number(lead.custom_fields.score) : null;
  let scoreColor = 'var(--muted)';
  if (score !== null) { if (score >= 8) scoreColor = '#10B981'; else if (score >= 5) scoreColor = '#F59E0B'; else scoreColor = '#EF4444'; }
  // Stage color accent
  const stageObj = (typeof crmStages !== 'undefined') ? crmStages.find(function(s){ return s.key === lead.stage; }) : null;
  const stageColor = stageObj ? stageObj.color : 'var(--muted)';
  // Avatar initials
  const avatarPalette = ['#3B82F6','#10B981','#F59E0B','#8B5CF6','#EC4899','var(--blue)','#14B8A6','#EF4444'];
  const avatarBg = avatarPalette[(lead.name || 'A').charCodeAt(0) % avatarPalette.length];
  const nameParts = (lead.name || '?').split(' ').filter(Boolean);
  const initials = nameParts.slice(0,2).map(function(w){ return w[0]; }).join('').toUpperCase();
  // Quick action buttons
  const phoneNum = (lead.phone || '').replace(/\s/g,'');
  const phoneBtn = lead.phone ? '<button class="crm-card-act-btn" onclick="event.stopPropagation();window.location.href=\'tel:' + phoneNum + '\'" title="Llamar"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.81a19.79 19.79 0 01-3.07-8.68A2 2 0 012 .13h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.09 7.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14.93z"/></svg> Llamar</button>' : '';
  const waBtn = lead.phone ? '<button class="crm-card-act-btn wa-btn" onclick="event.stopPropagation();window.open(\'https://wa.me/' + phoneNum.replace(/\D/g,'') + '\',\'_blank\')" title="WhatsApp"><svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" stroke="none"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347zM12 0C5.373 0 0 5.373 0 12c0 2.124.557 4.122 1.532 5.862L0 24l6.272-1.516C7.993 23.46 9.966 24 12 24c6.627 0 12-5.373 12-12S18.627 0 12 0zm0 22c-1.933 0-3.74-.511-5.29-1.402l-.38-.225-3.725.9.934-3.613-.247-.394C2.504 15.63 2 13.865 2 12 2 6.477 6.477 2 12 2s10 4.477 10 10-4.477 10-10 10z"/></svg> WhatsApp</button>' : '';
  const emailBtn = lead.email ? '<button class="crm-card-act-btn em-btn" onclick="event.stopPropagation();window.location.href=\'mailto:' + esc(lead.email) + '\'" title="Email"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg> Email</button>' : '';
  const hasActions = lead.phone || lead.email;
  return '<div class="crm-card" data-id="' + esc(lead.id) + '" style="border-left-color:' + stageColor + '">' +
    '<div class="crm-card-inner">' +
    '<div class="crm-card-top">' +
    '<div class="crm-card-name">' + esc(lead.name) + '</div>' +
    '<div class="crm-card-avatar" style="background:' + avatarBg + '">' + initials + '</div>' +
    '</div>' +
    (lead.company ? '<div class="crm-card-company"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/></svg>' + esc(lead.company) + '</div>' : '') +
    (lead.phone ? '<div class="crm-card-phone"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.81a19.79 19.79 0 01-3.07-8.68A2 2 0 012 .13h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.09 7.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14.93z"/></svg>' + esc(lead.phone) + '</div>' : '') +
    ((lead.tags || []).length ? '<div class="crm-card-tags">' + lead.tags.slice(0, 3).map(t => tagChipHtml(t)).join('') + (lead.tags.length > 3 ? '<span class="tag-chip tag-more">+' + (lead.tags.length - 3) + '</span>' : '') + '</div>' : '') +
    '<div class="crm-card-footer">' +
    '<div class="crm-card-source">' + esc(sourceLabels[lead.source] || lead.source || 'Manual') +
    (lead.assigned_name ? ' <span title="Asignado a ' + esc(lead.assigned_name) + '" style="display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:50%;background:var(--blue-lt);color:var(--blue);font-size:8.5px;font-weight:800;vertical-align:middle;margin-left:4px">' + esc(lead.assigned_name.slice(0, 2).toUpperCase()) + '</span>' : '') + '</div>' +
    (lead.value ? '<div class="crm-card-value">$' + Number(lead.value).toLocaleString('es-CO') + '</div>' : '') +
    '</div>' +
    ((score !== null || showInactive) ? '<div class="crm-card-badges">' +
    (score !== null ? '<div class="crm-card-score" style="background:' + scoreColor + '20;color:' + scoreColor + '">Score ' + score + '/10</div>' : '') +
    (showInactive ? '<div class="crm-card-inactive"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>' + daysSince + ' días sin actividad</div>' : '') +
    '</div>' : '') +
    '</div>' +
    (hasActions ? '<div class="crm-card-actions">' + phoneBtn + waBtn + emailBtn + '</div>' : '') +
    '</div>';
}

function crmSetupDrop(el, stageKey) {
  el.addEventListener('dragover', e => { e.preventDefault(); el.classList.add('drag-over'); });
  el.addEventListener('dragleave', () => el.classList.remove('drag-over'));
  el.addEventListener('drop', async e => {
    e.preventDefault();
    el.classList.remove('drag-over');
    const leadId = e.dataTransfer.getData('text/plain');
    if (!leadId) return;
    const lead = crmLeads.find(l => l.id === leadId);
    if (!lead || lead.stage === stageKey) return;
    const oldStage = lead.stage;
    lead.stage = stageKey;
    crmRenderKanban();
    try {
      await fetch(`/api/leads`, {
        method: 'PUT',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: leadId, stage: stageKey }),
      });
      // log stage change activity
      await fetch('/api/lead-activities', {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify({ lead_id: leadId, type: 'stage_change', content: `Movido de ${oldStage} a ${stageKey}`, metadata: { from: oldStage, to: stageKey } }),
      });
    } catch(e) { console.error('crmDrop', e); }
  });
}

function crmRenderList() {
  const tbody = document.getElementById('crm-list-body');
  if (!tbody) return;
  const sourceLabels = { manual: 'Manual', meta_ads: 'Meta Ads', google_ads: 'Google Ads', organico: 'Orgánico', referido: 'Referido', web: 'Web' };
  const filtered = crmGetFilteredLeads();
  if (filtered.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;color:var(--muted);padding:40px">Sin leads' + (crmSearchQuery || crmFilterSource ? ' que coincidan con los filtros.' : ' aún. Crea el primero.') + '</td></tr>';
    return;
  }
  tbody.innerHTML = filtered.map(l => {
    const stage = crmStages.find(s => s.key === l.stage) || { label: l.stage, color: 'var(--muted)' };
    return '<tr onclick="crmOpenDetail(\'' + esc(l.id) + '\')"><td style="font-weight:600">' + esc(l.name) + (l.company ? '<div style="font-size:11px;color:var(--muted);font-weight:400">' + esc(l.company) + '</div>' : '') + ((l.tags || []).length ? '<div class="crm-card-tags" style="margin-top:3px">' + l.tags.slice(0, 3).map(t => tagChipHtml(t)).join('') + (l.tags.length > 3 ? '<span class="tag-chip tag-more">+' + (l.tags.length - 3) + '</span>' : '') + '</div>' : '') + '</td><td style="color:var(--muted)">' + esc(l.email || '—') + '</td><td style="color:var(--muted)">' + esc(l.phone || '—') + '</td><td><span class="crm-stage-pill" style="background:' + esc(stage.color) + '20;color:' + esc(stage.color) + '">' + esc(stage.label) + '</span></td><td style="font-size:11px;color:var(--muted)">' + esc(sourceLabels[l.source] || l.source || 'Manual') + '</td><td style="font-size:11px;color:var(--muted2)">' + (l.value ? '$' + Number(l.value).toLocaleString('es-CO') : '—') + '</td></tr>';
  }).join('');
  crmUpdateLeadsStats();
}

function crmUpdateClientTag() {
  const tag = document.getElementById('crm-client-tag');
  const nameEl = document.getElementById('crm-client-tag-name');
  const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
  if (tag && clientId) {
    tag.style.display = 'flex';
    if (nameEl) {
      const clients = typeof agencyClients !== 'undefined' ? agencyClients : [];
      const c = clients.find(x => x.id === clientId);
      nameEl.textContent = c ? c.name : clientId;
    }
  } else if (tag) {
    tag.style.display = 'none';
  }
}

function crmUpdateSidebarCount() {
  const el = document.getElementById('sb-leads-count');
  if (el) el.textContent = crmLeads.length;
  const btn = document.getElementById('sb-leads-btn');
  if (btn) btn.style.display = 'block';
}

// ── Modal crear/editar ────────────────────────────────────────────────────────
function crmOpenModal(defaultStage) {
  crmEditingId = null;
  document.getElementById('crm-modal-title').textContent = 'Nuevo lead';
  document.getElementById('crm-f-name').value = '';
  document.getElementById('crm-f-email').value = '';
  document.getElementById('crm-f-phone').value = '';
  document.getElementById('crm-f-company').value = '';
  document.getElementById('crm-f-notes').value = '';
  document.getElementById('crm-f-source').value = 'manual';
  const valModalEl = document.getElementById('crm-f-value');
  if (valModalEl) valModalEl.value = '';
  const tagsModalEl = document.getElementById('crm-f-tags');
  if (tagsModalEl) tagsModalEl.value = '';
  crmPopulateStageSelects();
  if (defaultStage) document.getElementById('crm-f-stage').value = defaultStage;
  document.getElementById('crm-save-btn').disabled = false;
  document.getElementById('crm-modal').classList.add('open');
  setTimeout(() => document.getElementById('crm-f-name').focus(), 100);
}

function crmCloseModal() {
  document.getElementById('crm-modal').classList.remove('open');
  crmEditingId = null;
}

async function crmSaveLead() {
  const name = document.getElementById('crm-f-name').value.trim();
  if (!name) { document.getElementById('crm-f-name').focus(); return; }
  const btn = document.getElementById('crm-save-btn');
  btn.disabled = true;
  btn.textContent = 'Guardando...';
  const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
  const payload = {
    name,
    email: document.getElementById('crm-f-email').value.trim() || null,
    phone: document.getElementById('crm-f-phone').value.trim() || null,
    company: document.getElementById('crm-f-company').value.trim() || null,
    stage: document.getElementById('crm-f-stage').value,
    source: document.getElementById('crm-f-source').value,
    notes: document.getElementById('crm-f-notes').value.trim() || null,
    client_id: clientId,
    value: parseFloat(document.getElementById('crm-f-value').value) || null,
    tags: document.getElementById('crm-f-tags') && document.getElementById('crm-f-tags').value.trim() ? document.getElementById('crm-f-tags').value.split(',').map(t => t.trim()).filter(Boolean) : null,
  };
  try {
    if (crmEditingId) {
      payload.id = crmEditingId;
      const res = await fetch('/api/leads', {
        method: 'PUT',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error();
      const data = await res.json();
      const idx = crmLeads.findIndex(l => l.id === crmEditingId);
      if (idx >= 0) crmLeads[idx] = data.lead;
    } else {
      const qs = clientId ? `?client_id=${encodeURIComponent(clientId)}` : '';
      const res = await fetch(`/api/leads${qs}`, {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        if (res.status === 403 && errData.limit_reached) {
          btn.textContent = 'Guardar';
          btn.disabled = false;
          crmCloseModal();
          const planLabel = userPlan === 'pro' ? 'Pro (1.000 leads)' : userPlan === 'agency' ? 'Agency (5.000 leads)' : 'Free (10 leads)';
          openUpgradeFlow('Alcanzaste el límite de leads de tu plan ' + planLabel + '. Actualiza para agregar más contactos.');
          return;
        }
        throw new Error();
      }
      const data = await res.json();
      crmLeads.unshift(data.lead);
      track('crm_lead_created', { source: data.lead.source || 'manual' });
      // log creation activity
      await fetch('/api/lead-activities', {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify({ lead_id: data.lead.id, type: 'creacion', content: 'Lead creado', metadata: {} }),
      });
    }
    crmCloseModal();
    crmRender();
  } catch(e) {
    console.error('crmSaveLead', e);
    btn.textContent = 'Error — reintentar';
    btn.disabled = false;
  }
}

// ── Panel de detalle ──────────────────────────────────────────────────────────
async function crmOpenDetail(leadId) {
  const lead = crmLeads.find(l => l.id === leadId);
  if (!lead) return;
  crmDetailLead = lead;
  const sourceLabels = { manual: 'Manual', meta_ads: 'Meta Ads', google_ads: 'Google Ads', organico: 'Orgánico', referido: 'Referido', web: 'Web' };
  document.getElementById('crm-d-name').textContent = lead.name;
  // Avatar
  const avatarPalette = ['#3B82F6','#10B981','#F59E0B','#8B5CF6','#EC4899','var(--blue)','#14B8A6','#EF4444'];
  const avatarBg = avatarPalette[(lead.name || 'A').charCodeAt(0) % avatarPalette.length];
  const avatarInitials = (lead.name || '?').split(' ').filter(Boolean).slice(0,2).map(function(w){ return w[0]; }).join('').toUpperCase();
  const avatarEl = document.getElementById('crm-d-avatar');
  if (avatarEl) { avatarEl.textContent = avatarInitials; avatarEl.style.background = avatarBg; }
  // Quick action buttons
  const qaPhone = (lead.phone || '').replace(/\s/g,'');
  const qaEl = document.getElementById('crm-d-quick-actions');
  if (qaEl) {
    qaEl.innerHTML =
      (lead.phone ? '<a class="crm-qa-btn" href="tel:' + qaPhone + '"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.81a19.79 19.79 0 01-3.07-8.68A2 2 0 012 .13h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.09 7.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14.93z"/></svg> Llamar</a>' : '') +
      (lead.phone ? '<a class="crm-qa-btn wa" href="https://wa.me/' + qaPhone.replace(/\D/g,'') + '" target="_blank"><svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" stroke="none"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347zM12 0C5.373 0 0 5.373 0 12c0 2.124.557 4.122 1.532 5.862L0 24l6.272-1.516C7.993 23.46 9.966 24 12 24c6.627 0 12-5.373 12-12S18.627 0 12 0zm0 22c-1.933 0-3.74-.511-5.29-1.402l-.38-.225-3.725.9.934-3.613-.247-.394C2.504 15.63 2 13.865 2 12 2 6.477 6.477 2 12 2s10 4.477 10 10-4.477 10-10 10z"/></svg> WhatsApp</a>' : '') +
      (lead.email ? '<a class="crm-qa-btn em" href="mailto:' + esc(lead.email) + '"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg> Email</a>' : '') +
      '<button class="crm-qa-btn" style="border-color:var(--blue-md);color:var(--blue);background:var(--blue-lt);cursor:pointer;font-family:var(--font)" onclick="crmSendLeadToConsultor()" title="El Consultor analiza el lead y prepara el seguimiento">✨ Enviar al Consultor</button>' +
      '<button class="crm-qa-btn" style="cursor:pointer;font-family:var(--font)" onclick="agnScheduleForLead()" title="Crear tarea o reunión con este lead (sincroniza con Google Calendar)">📅 Agendar</button>' +
      '<button class="crm-qa-btn" style="cursor:pointer;font-family:var(--font);border-color:#A7F3D0;background:#ECFDF5;color:#059669" onclick="prpOpenForLead()" title="Generar y enviar una propuesta comercial con link de pago">📄 Propuesta</button>';
  }
  document.getElementById('crm-d-email').textContent = lead.email || '—';
  document.getElementById('crm-d-phone').textContent = lead.phone || '—';
  document.getElementById('crm-d-company').textContent = lead.company || '—';
  document.getElementById('crm-d-source').textContent = sourceLabels[lead.source] || lead.source || 'Manual';
  const valueRow = document.getElementById('crm-d-value-row');
  if (valueRow) { valueRow.style.display = lead.value ? 'flex' : 'none'; const valEl = document.getElementById('crm-d-value'); if (valEl) valEl.textContent = lead.value ? '$' + Number(lead.value).toLocaleString('es-CO') : ''; }
  crmRenderDetailTags();
  teamEnsureLoaded().then(() => teamPopulateAssign(lead));
  const notesSection = document.getElementById('crm-d-notes-section');
  if (lead.notes) {
    notesSection.style.display = 'flex';
    document.getElementById('crm-d-notes').textContent = lead.notes;
  } else {
    notesSection.style.display = 'none';
  }
  crmPopulateStageSelects();
  document.getElementById('crm-d-stage').value = lead.stage;
  document.getElementById('crm-detail-overlay').classList.add('open');
  document.getElementById('crm-detail-panel').classList.add('open');
  document.getElementById('crm-activity-input').value = '';
  // Reset suggest result
  const suggestResult = document.getElementById('crm-d-suggest-result');
  if (suggestResult) suggestResult.style.display = 'none';
  await Promise.all([crmLoadActivities(leadId), crmLoadLinkedConversations(leadId)]);
}

// Editor de etiquetas en el detalle: chips con ✕ + input con autocompletado
function crmRenderDetailTags() {
  const row = document.getElementById('crm-d-tags-row');
  if (!row || !crmDetailLead) return;
  row.style.display = 'flex';
  const tags = crmDetailLead.tags || [];
  const el = document.getElementById('crm-d-tags');
  if (!el) return;
  el.innerHTML = '<div class="crm-d-tags-wrap">' +
    tags.map(t => tagChipHtml(t, true)).join('') +
    '<input class="crm-d-tag-input" id="crm-d-tag-input" list="crm-tag-datalist" placeholder="+ etiqueta" ' +
      'onkeydown="if(event.key===\'Enter\'){event.preventDefault();crmDetailAddTag(this.value);this.value=\'\'}" ' +
      'onchange="if(this.value){crmDetailAddTag(this.value);this.value=\'\'}">' +
    '<datalist id="crm-tag-datalist">' + crmTags.filter(t => !tags.includes(t.name)).map(t => '<option value="' + esc(t.name) + '">').join('') + '</datalist>' +
    '</div>';
}

async function crmDetailSaveTags(newTags) {
  if (!crmDetailLead) return;
  const lead = crmDetailLead;
  const prev = lead.tags || [];
  lead.tags = newTags;
  crmRenderDetailTags();
  crmRender();
  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    const qs = clientId ? '?client_id=' + encodeURIComponent(clientId) : '';
    const res = await fetch('/api/leads' + qs, { method: 'PUT', headers: await getAuthHeaders(), body: JSON.stringify({ id: lead.id, tags: newTags }) });
    const d = await res.json();
    if (d.lead) { lead.tags = d.lead.tags || newTags; }
    await crmLoadTags(); // refrescar catálogo (colores de etiquetas nuevas)
    crmRenderDetailTags();
    crmRender();
  } catch (e) {
    lead.tags = prev;
    crmRenderDetailTags();
    crmRender();
    showToast('No se pudo guardar la etiqueta', 'error');
  }
}

async function crmDetailAddTag(name) {
  const n = normalizeTag(name);
  if (n.length < 2 || !crmDetailLead) return;
  const tags = crmDetailLead.tags || [];
  if (tags.includes(n)) return;
  if (tags.length >= 15) { showToast('Máximo 15 etiquetas por lead', 'error'); return; }
  await crmEnsureTag(n);
  crmDetailSaveTags([...tags, n]);
}

function crmDetailRemoveTag(name) {
  if (!crmDetailLead) return;
  crmDetailSaveTags((crmDetailLead.tags || []).filter(t => t !== name));
}

function crmCloseDetail() {
  document.getElementById('crm-detail-overlay').classList.remove('open');
  document.getElementById('crm-detail-panel').classList.remove('open');
  crmDetailLead = null;
}

async function crmLoadLinkedConversations(leadId) {
  const section = document.getElementById('crm-d-convs-section');
  const list = document.getElementById('crm-d-convs-list');
  if (!section || !list) return;
  try {
    const res = await fetch('/api/chat-conversations?lead_id=' + encodeURIComponent(leadId), { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    const convs = data.conversations || [];
    if (convs.length === 0) { section.style.display = 'none'; return; }
    const channelIcons = { whatsapp: '💬', messenger: '💙', instagram: '📸' };
    const channelColors = { whatsapp: '#DCFCE7', messenger: '#DBEAFE', instagram: '#FCE7F3' };
    list.innerHTML = convs.map(c => {
      const icon = channelIcons[c.channel] || '💬';
      const bg = channelColors[c.channel] || 'var(--bg-muted)';
      const name = c.contact_name || c.contact_id || 'Contacto';
      const preview = c.last_message ? c.last_message.slice(0, 60) + (c.last_message.length > 60 ? '…' : '') : 'Sin mensajes';
      const time = c.last_message_at ? new Date(c.last_message_at).toLocaleDateString('es-CO', { day: '2-digit', month: 'short' }) : '';
      return '<div class="crm-linked-conv" onclick="crmOpenConvFromDetail(\'' + esc(c.id) + '\',\'' + esc(c.channel) + '\')">' +
        '<div class="crm-linked-conv-icon" style="background:' + bg + '">' + icon + '</div>' +
        '<div class="crm-linked-conv-info">' +
        '<div class="crm-linked-conv-name">' + esc(name) + '</div>' +
        '<div class="crm-linked-conv-preview">' + esc(preview) + '</div>' +
        '</div>' +
        '<div class="crm-linked-conv-time">' + esc(time) + '</div>' +
        '</div>';
    }).join('');
    section.style.display = 'flex';
  } catch(e) { section.style.display = 'none'; }
}

function crmOpenConvFromDetail(convId, channel) {
  crmCloseDetail();
  crmSetView('inbox');
  setTimeout(function() {
    const btn = document.querySelector('[data-conv-id="' + convId + '"]');
    if (btn) btn.click();
  }, 300);
}

async function crmSuggestNextAction() {
  if (!crmDetailLead) return;
  const btn = document.getElementById('crm-suggest-btn');
  const resultEl = document.getElementById('crm-d-suggest-result');
  if (btn) { btn.disabled = true; btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg> Analizando...'; }
  try {
    const lead = crmDetailLead;
    const stage = (crmStages.find(function(s){ return s.key === lead.stage; }) || { label: lead.stage }).label;
    const lastActive = lead.updated_at ? new Date(lead.updated_at).getTime() : new Date(lead.created_at || 0).getTime();
    const daysSince = Math.floor((Date.now() - lastActive) / 86400000);
    // Fetch recent activities for context
    let actContext = '';
    try {
      const ar = await fetch('/api/lead-activities?lead_id=' + encodeURIComponent(lead.id), { headers: await getAuthHeaders() });
      const ad = await ar.json();
      const acts = (ad.activities || []).slice(0, 5);
      const typeLabels = { nota: 'Nota', llamada: 'Llamada', email: 'Email', reunion: 'Reunión', tarea: 'Tarea', stage_change: 'Cambio etapa', creacion: 'Creación' };
      actContext = acts.map(function(a){ return typeLabels[a.type] + ': ' + (a.content || '').slice(0, 80); }).join('\n');
    } catch(e) {}
    const prompt = 'Eres un experto en ventas y CRM. Analiza este lead y sugiere la próxima acción concreta.\n\nLead: ' + lead.name + (lead.company ? ' (' + lead.company + ')' : '') + '\nEtapa: ' + stage + '\nDías sin actividad: ' + daysSince + '\nFuente: ' + (lead.source || 'Manual') + '\nValor del deal: ' + (lead.value ? '$' + Number(lead.value).toLocaleString('es-CO') : 'No definido') + '\nNotas: ' + (lead.notes || 'Sin notas') + '\n\nÚltimas actividades:\n' + (actContext || 'Sin actividades registradas') + '\n\nResponde en 2-3 oraciones máximo con una acción específica, concreta y con urgencia apropiada. Empieza directamente con la recomendación (no digas "te recomiendo" ni "sugiero"). Sé directo.';
    const res = await fetch('/api/chat', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: prompt, agent: 'consultor', noPersist: true }),
    });
    if (!res.ok) throw new Error();
    const data = await res.json();
    const suggestion = data.reply || data.content || '';
    if (resultEl && suggestion) {
      resultEl.style.display = 'block';
      resultEl.innerHTML = '<div class="crm-suggest-result"><div class="crm-suggest-result-title">Próxima acción sugerida</div>' + esc(suggestion) + '</div>';
    }
  } catch(e) {
    if (resultEl) { resultEl.style.display = 'block'; resultEl.innerHTML = '<div style="font-size:12px;color:var(--muted)">No se pudo generar la sugerencia.</div>'; }
  }
  if (btn) { btn.disabled = false; btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg> Sugerir próxima acción'; }
}

async function crmChangeStage(newStage) {
  if (!crmDetailLead) return;
  const leadId = crmDetailLead.id;
  const oldStage = crmDetailLead.stage;
  if (oldStage === newStage) return;
  crmDetailLead.stage = newStage;
  const lead = crmLeads.find(l => l.id === leadId);
  if (lead) lead.stage = newStage;
  crmRender();
  try {
    await fetch('/api/leads', {
      method: 'PUT',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: leadId, stage: newStage }),
    });
    await fetch('/api/lead-activities', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ lead_id: leadId, type: 'stage_change', content: `Etapa cambiada de "${oldStage}" a "${newStage}"`, metadata: { from: oldStage, to: newStage } }),
    });
    await crmLoadActivities(leadId);
  } catch(e) { console.error('crmChangeStage', e); }
}

async function crmLoadActivities(leadId) {
  const list = document.getElementById('crm-activity-list');
  if (!list) return;
  try {
    const res = await fetch(`/api/lead-activities?lead_id=${encodeURIComponent(leadId)}`, { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    const acts = data.activities || [];
    if (acts.length === 0) {
      list.innerHTML = `<div style="font-size:12px;color:var(--muted)">Sin actividad registrada.</div>`;
      return;
    }
    const typeLabels = { nota: 'Nota', llamada: 'Llamada', email: 'Email', reunion: 'Reunión', tarea: 'Tarea', stage_change: 'Etapa', creacion: 'Creado' };
    const typeColors = { nota: 'var(--blue)', llamada: '#10B981', email: '#6366F1', reunion: '#F59E0B', tarea: '#EF4444', stage_change: '#10B981', creacion: 'var(--muted2)' };
    list.innerHTML = acts.map(a => {
      const dueDate = a.metadata && a.metadata.due_date ? '<div style="font-size:10px;color:#D97706;margin-top:2px">Fecha límite: ' + new Date(a.metadata.due_date).toLocaleString('es-CO', { dateStyle: 'short', timeStyle: 'short' }) + '</div>' : '';
      return '<div class="crm-activity-item"><div class="crm-activity-dot" style="background:' + (typeColors[a.type] || 'var(--blue)') + '"></div><div class="crm-activity-content"><div class="crm-activity-text"><strong>' + esc(typeLabels[a.type] || a.type) + ':</strong> ' + esc(a.content || '') + '</div>' + dueDate + '<div class="crm-activity-time">' + new Date(a.created_at).toLocaleString('es-CO', { dateStyle: 'short', timeStyle: 'short' }) + '</div></div></div>';
    }).join('');
  } catch(e) { console.error('crmLoadActivities', e); }
}

function crmSetActType(type, btn) {
  crmActivityType = type;
  document.querySelectorAll('.crm-act-type-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const dueWrap = document.getElementById('crm-act-due-wrap');
  if (dueWrap) dueWrap.style.display = type === 'tarea' ? 'block' : 'none';
  const placeholders = { nota: 'Escribe una nota sobre este lead...', llamada: 'Resultado de la llamada...', email: 'Resumen del email enviado o recibido...', reunion: 'Puntos clave de la reunión...', tarea: 'Describe la tarea pendiente...' };
  const input = document.getElementById('crm-activity-input');
  if (input) input.placeholder = placeholders[type] || '';
}

async function crmAddActivity() {
  if (!crmDetailLead) return;
  const input = document.getElementById('crm-activity-input');
  const content = input.value.trim();
  if (!content) return;
  const btn = document.querySelector('.crm-activity-btn');
  if (btn) btn.disabled = true;
  const metadata = {};
  if (crmActivityType === 'tarea') {
    const dueInput = document.getElementById('crm-act-due');
    if (dueInput && dueInput.value) metadata.due_date = dueInput.value;
  }
  try {
    await fetch('/api/lead-activities', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ lead_id: crmDetailLead.id, type: crmActivityType, content, metadata }),
    });
    input.value = '';
    const dueInput = document.getElementById('crm-act-due');
    if (dueInput) dueInput.value = '';
    await crmLoadActivities(crmDetailLead.id);
  } catch(e) { console.error('crmAddActivity', e); }
  if (btn) btn.disabled = false;
}

function crmEditCurrentLead() {
  if (!crmDetailLead) return;
  crmCloseDetail();
  crmEditingId = crmDetailLead.id;
  document.getElementById('crm-modal-title').textContent = 'Editar lead';
  document.getElementById('crm-f-name').value = crmDetailLead.name || '';
  document.getElementById('crm-f-email').value = crmDetailLead.email || '';
  document.getElementById('crm-f-phone').value = crmDetailLead.phone || '';
  document.getElementById('crm-f-company').value = crmDetailLead.company || '';
  document.getElementById('crm-f-notes').value = crmDetailLead.notes || '';
  document.getElementById('crm-f-source').value = crmDetailLead.source || 'manual';
  const valEditEl = document.getElementById('crm-f-value');
  if (valEditEl) valEditEl.value = crmDetailLead.value || '';
  const tagsEditEl = document.getElementById('crm-f-tags');
  if (tagsEditEl) tagsEditEl.value = (crmDetailLead.tags || []).join(', ');
  crmPopulateStageSelects();
  document.getElementById('crm-f-stage').value = crmDetailLead.stage;
  document.getElementById('crm-save-btn').disabled = false;
  document.getElementById('crm-save-btn').textContent = 'Guardar';
  document.getElementById('crm-modal').classList.add('open');
}

async function crmDeleteCurrentLead() {
  if (!crmDetailLead) return;
  if (!confirm(`¿Eliminar el lead "${crmDetailLead.name}"? Esta acción no se puede deshacer.`)) return;
  const leadId = crmDetailLead.id;
  crmCloseDetail();
  try {
    await fetch(`/api/leads?id=${encodeURIComponent(leadId)}`, {
      method: 'DELETE',
      headers: await getAuthHeaders(),
    });
    crmLeads = crmLeads.filter(l => l.id !== leadId);
    crmRender();
  } catch(e) { console.error('crmDeleteCurrentLead', e); }
}
// ── AGENTES IA / INBOX ───────────────────────────────────────────────────────
let crmAgents = [];
let inboxConversations = [];
let inboxActiveConvId = null;
let inboxFilter = 'all';
let agEditingId = null;
let agFaqs = [];

// ── Vista de Agentes ──────────────────────────────────────────────────────────
async function crmLoadAgents() {
  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    const qs = clientId ? `?client_id=${encodeURIComponent(clientId)}` : '';
    const res = await fetch(`/api/chat-agents${qs}`, { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    crmAgents = data.agents || [];
    crmRenderAgents();
  } catch(e) { console.error('crmLoadAgents', e); }
}

function crmRenderAgents() {
  const list = document.getElementById('crm-agents-list');
  if (!list) return;
  if (crmAgents.length === 0) {
    list.innerHTML = '';
    return;
  }
  const channelIcons = { messenger: '💬', instagram: '📷', whatsapp: '📱', tiktok: '🎵' };
  list.innerHTML = crmAgents.map(ag => {
    const connections = ag.channel_connections || [];
    const activeConns = connections.filter(c => c.is_active);
    return `<div class="crm-agent-card" onclick="crmOpenAgentModal('${esc(ag.id)}')">
      <div class="crm-agent-avatar">${esc(ag.name.charAt(0).toUpperCase())}</div>
      <div class="crm-agent-info">
        <div class="crm-agent-name">${esc(ag.name)}</div>
        <div class="crm-agent-desc">${esc((ag.business_ctx || 'Sin contexto de negocio').slice(0, 80))}${(ag.business_ctx || '').length > 80 ? '...' : ''}</div>
        <div class="crm-agent-channels">
          ${activeConns.length === 0 ? '<span class="crm-channel-badge inactive">Sin canales</span>' : activeConns.map(c => `<span class="crm-channel-badge ${c.channel}">${channelIcons[c.channel] || ''} ${esc(c.channel_name || c.channel)}</span>`).join('')}
        </div>
      </div>
      <div class="crm-agent-status ${ag.is_active ? 'active' : 'inactive'}"></div>
    </div>`;
  }).join('');
}

// ── Modal Agente ──────────────────────────────────────────────────────────────
function crmOpenAgentModal(agentId) {
  agEditingId = agentId || null;
  agFaqs = [];
  const isEdit = !!agentId;
  document.getElementById('crm-agent-modal-title').textContent = isEdit ? 'Editar agente' : 'Nuevo agente de IA';
  document.getElementById('ag-save-btn').textContent = isEdit ? 'Guardar cambios' : 'Crear agente';

  if (isEdit) {
    const ag = crmAgents.find(a => a.id === agentId);
    if (!ag) return;
    document.getElementById('cag-f-name').value = ag.name || '';
    document.getElementById('cag-f-persona').value = ag.persona || '';
    document.getElementById('cag-f-business').value = ag.business_ctx || '';
    document.getElementById('cag-f-escalate').value = ag.escalate_phrase || '';
    document.getElementById('cag-f-tone').value = ag.tone || 'informal';
    agFaqs = (ag.faqs || []).map(f => ({ ...f }));
    // Show channels section
    const chSect = document.getElementById('ag-channels-section');
    if (chSect) { chSect.style.display = 'block'; agRenderChannels(ag); }
  } else {
    document.getElementById('cag-f-name').value = '';
    document.getElementById('cag-f-persona').value = '';
    document.getElementById('cag-f-business').value = '';
    document.getElementById('cag-f-escalate').value = 'Claro, en un momento te comunico con un asesor. ¿Me das un segundo?';
    document.getElementById('cag-f-tone').value = 'informal';
    const chSect = document.getElementById('ag-channels-section');
    if (chSect) chSect.style.display = 'none';
  }
  agRenderFaqs();
  document.getElementById('crm-agent-modal').classList.add('open');
  setTimeout(() => document.getElementById('cag-f-name').focus(), 100);
}

function crmCloseAgentModal() {
  document.getElementById('crm-agent-modal').classList.remove('open');
  agEditingId = null;
  agFaqs = [];
}

function agRenderFaqs() {
  const list = document.getElementById('ag-faqs-list');
  if (!list) return;
  if (agFaqs.length === 0) { list.innerHTML = ''; return; }
  list.innerHTML = agFaqs.map((f, i) => `
    <div class="crm-faq-item">
      <div style="flex:1;display:flex;flex-direction:column;gap:5px">
        <input class="crm-faq-input" placeholder="Pregunta (ej: ¿Cuáles son los precios?)" value="${esc(f.q || '')}" oninput="agFaqs[${i}].q=this.value" />
        <input class="crm-faq-input" placeholder="Respuesta" value="${esc(f.a || '')}" oninput="agFaqs[${i}].a=this.value" />
      </div>
      <button class="crm-faq-del" onclick="agRemoveFaq(${i})">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M18 6L6 18M6 6l12 12"/></svg>
      </button>
    </div>`).join('');
}

function agAddFaq() {
  agFaqs.push({ q: '', a: '' });
  agRenderFaqs();
}

function agRemoveFaq(i) {
  agFaqs.splice(i, 1);
  agRenderFaqs();
}

function agRenderChannels(agent) {
  const list = document.getElementById('ag-channels-list');
  if (!list) return;
  const conns = agent.channel_connections || [];
  const channels = [
    { key: 'whatsapp', label: 'WhatsApp Business', icon: '📱', color: '#128C7E', desc: 'Conecta un número de WhatsApp Business' },
    { key: 'messenger', label: 'Messenger', icon: '💬', color: '#1877F2', desc: 'Conecta una Página de Facebook' },
    { key: 'instagram', label: 'Instagram DMs', icon: '📷', color: '#C13584', desc: 'Conecta una cuenta Instagram Business' },
  ];
  list.innerHTML = channels.map(ch => {
    const conn = conns.find(c => c.channel === ch.key && c.is_active);
    return `<div class="crm-channel-connect-row">
      <div class="crm-channel-icon" style="background:${ch.color}20">${ch.icon}</div>
      <div class="crm-channel-connect-info">
        <div class="crm-channel-connect-name">${ch.label}</div>
        <div class="crm-channel-connect-status">${conn ? `Conectado: ${esc(conn.channel_name || conn.external_id)}` : ch.desc}</div>
      </div>
      ${conn
        ? `<button class="crm-channel-btn disconnect" onclick="agDisconnectChannel('${esc(conn.id)}','${esc(agent.id)}')">Desconectar</button>`
        : `<button class="crm-channel-btn connect" onclick="agConnectChannel('${esc(ch.key)}','${esc(agent.id)}')">Conectar</button>`
      }
    </div>`;
  }).join('');
}

async function crmSaveAgent() {
  const name = document.getElementById('cag-f-name').value.trim();
  if (!name) { document.getElementById('cag-f-name').focus(); return; }
  const btn = document.getElementById('ag-save-btn');
  btn.disabled = true; btn.textContent = 'Guardando...';

  const payload = {
    name,
    persona: document.getElementById('cag-f-persona').value.trim(),
    business_ctx: document.getElementById('cag-f-business').value.trim(),
    escalate_phrase: document.getElementById('cag-f-escalate').value.trim(),
    tone: document.getElementById('cag-f-tone').value,
    faqs: agFaqs.filter(f => f.q && f.a),
  };

  try {
    const clientId = typeof agencyActiveClientId !== 'undefined' ? agencyActiveClientId : null;
    if (agEditingId) {
      payload.id = agEditingId;
      const res = await fetch('/api/chat-agents', {
        method: 'PUT',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error();
    } else {
      const qs = clientId ? `?client_id=${encodeURIComponent(clientId)}` : '';
      const res = await fetch(`/api/chat-agents${qs}`, {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error();
    }
    crmCloseAgentModal();
    await crmLoadAgents();
  } catch(e) {
    console.error('crmSaveAgent', e);
    btn.textContent = 'Error — reintentar';
    btn.disabled = false;
  }
}

let _waConnectAgentId = null;

function waConnectOpen(agentId) {
  _waConnectAgentId = agentId;
  document.getElementById('wa-f-phone-id').value = '';
  document.getElementById('wa-f-token').value = '';
  document.getElementById('wa-f-name').value = '';
  const err = document.getElementById('wa-connect-error');
  if (err) { err.style.display = 'none'; err.textContent = ''; }
  const btn = document.getElementById('wa-connect-btn');
  if (btn) { btn.disabled = false; btn.textContent = 'Conectar'; }
  document.getElementById('wa-connect-modal').classList.add('open');
  setTimeout(() => document.getElementById('wa-f-phone-id').focus(), 100);
}

function waConnectClose() {
  document.getElementById('wa-connect-modal').classList.remove('open');
  _waConnectAgentId = null;
}

async function waConnectSave() {
  const phoneNumberId = document.getElementById('wa-f-phone-id').value.trim();
  const token = document.getElementById('wa-f-token').value.trim();
  const name = document.getElementById('wa-f-name').value.trim() || phoneNumberId;
  const errEl = document.getElementById('wa-connect-error');
  const btn = document.getElementById('wa-connect-btn');

  const showErr = (msg) => { errEl.textContent = msg; errEl.style.display = 'block'; btn.disabled = false; btn.textContent = 'Conectar'; };

  if (!phoneNumberId) { showErr('El Phone Number ID es obligatorio.'); document.getElementById('wa-f-phone-id').focus(); return; }
  if (!token) { showErr('El Access Token es obligatorio.'); document.getElementById('wa-f-token').focus(); return; }

  btn.disabled = true; btn.textContent = 'Verificando...';
  errEl.style.display = 'none';

  try {
    const testRes = await fetch(`https://graph.facebook.com/v19.0/${phoneNumberId}?access_token=${token}`);
    const testData = await testRes.json();
    if (testData.error) { showErr('Token o Phone Number ID inválido: ' + testData.error.message); return; }

    btn.textContent = 'Conectando...';
    const res = await fetch('/api/channel-connections', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ agent_id: _waConnectAgentId, channel: 'whatsapp', external_id: phoneNumberId, access_token: token, channel_name: name }),
    });
    if (!res.ok) { showErr('Error guardando la conexión. Verifica los datos e intenta de nuevo.'); return; }
    waConnectClose();
    await crmLoadAgents();
    crmOpenAgentModal(_waConnectAgentId);
  } catch(e) {
    showErr('Error de red. Verifica tu conexión e intenta de nuevo.');
  }
}

async function agConnectChannel(channel, agentId) {
  if (channel === 'whatsapp') {
    waConnectOpen(agentId);
    return;
  } else {
    // Messenger / Instagram: usar token Meta existente
    const metaToken = sessionStorage.getItem('metaToken') || localStorage.getItem('meta_access_token');
    if (!metaToken) {
      alert('Primero conecta tu cuenta de Meta en Configuración → Integraciones → Meta Ads');
      return;
    }
    const res = await fetch(`/api/channel-connections?action=list_pages&token=${encodeURIComponent(metaToken)}`, { headers: await getAuthHeaders() });
    if (!res.ok) { alert('Error listando páginas de Meta.'); return; }
    const data = await res.json();
    const pages = data.pages || [];
    if (pages.length === 0) { alert('No se encontraron páginas de Facebook administradas por esta cuenta.'); return; }

    let options = '';
    if (channel === 'messenger') {
      options = pages.map((p, i) => `${i + 1}. ${p.name} (ID: ${p.id})`).join('\n');
      const choice = prompt(`Selecciona el número de la página para Messenger:\n\n${options}`);
      const idx = parseInt(choice) - 1;
      if (isNaN(idx) || !pages[idx]) return;
      const page = pages[idx];
      // Get page access token
      const ptRes = await fetch(`https://graph.facebook.com/v19.0/${page.id}?fields=access_token&access_token=${metaToken}`);
      const ptData = await ptRes.json();
      const pageToken = ptData.access_token;
      const connRes = await fetch('/api/channel-connections', {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify({ agent_id: agentId, channel: 'messenger', external_id: page.id, access_token: pageToken, channel_name: page.name }),
      });
      if (connRes.ok) { await crmLoadAgents(); crmOpenAgentModal(agentId); }
    } else if (channel === 'instagram') {
      const igPages = pages.filter(p => p.instagram_business_account);
      if (igPages.length === 0) { alert('No se encontraron cuentas de Instagram Business conectadas a tus páginas.'); return; }
      options = igPages.map((p, i) => `${i + 1}. ${p.instagram_business_account.name || p.name}`).join('\n');
      const choice = prompt(`Selecciona la cuenta de Instagram:\n\n${options}`);
      const idx = parseInt(choice) - 1;
      if (isNaN(idx) || !igPages[idx]) return;
      const page = igPages[idx];
      const igAcct = page.instagram_business_account;
      const ptRes = await fetch(`https://graph.facebook.com/v19.0/${page.id}?fields=access_token&access_token=${metaToken}`);
      const ptData = await ptRes.json();
      const connRes = await fetch('/api/channel-connections', {
        method: 'POST',
        headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
        body: JSON.stringify({ agent_id: agentId, channel: 'instagram', external_id: igAcct.id, access_token: ptData.access_token, channel_name: igAcct.name || page.name }),
      });
      if (connRes.ok) { await crmLoadAgents(); crmOpenAgentModal(agentId); }
    }
  }
}

async function agDisconnectChannel(connId, agentId) {
  if (!confirm('¿Desconectar este canal? El agente dejará de responder mensajes por este canal.')) return;
  await fetch(`/api/channel-connections?id=${encodeURIComponent(connId)}`, {
    method: 'DELETE', headers: await getAuthHeaders(),
  });
  await crmLoadAgents();
  crmOpenAgentModal(agentId);
}

// ── Inbox ─────────────────────────────────────────────────────────────────────
async function crmLoadInbox(filterStatus) {
  if (filterStatus) inboxFilter = filterStatus;
  try {
    let qs = inboxFilter === 'all' ? '' : `&status=${inboxFilter}`;
    const res = await fetch(`/api/chat-conversations?${qs}`, { headers: await getAuthHeaders() });
    if (!res.ok) throw new Error();
    const data = await res.json();
    inboxConversations = data.conversations || [];
    inboxRenderList();
    inboxUpdateBadge();
  } catch(e) { console.error('crmLoadInbox', e); }
}

function inboxRenderList() {
  const list = document.getElementById('crm-inbox-conv-list');
  if (!list) return;
  const channelIcons = { messenger: '💬', instagram: '📷', whatsapp: '📱', tiktok: '🎵' };
  if (inboxConversations.length === 0) {
    list.innerHTML = '<div style="padding:20px;text-align:center;font-size:12px;color:var(--muted)">Sin conversaciones aún. Los mensajes de tus canales conectados aparecerán aquí.</div>';
    return;
  }
  list.innerHTML = inboxConversations.map(conv => {
    const name = conv.contact_name || conv.contact_phone || conv.contact_id || 'Desconocido';
    const time = conv.last_message_at ? timeAgo(conv.last_message_at) : '';
    return `<div class="crm-inbox-conv-item${inboxActiveConvId === conv.id ? ' active' : ''}" onclick="inboxOpenConv('${esc(conv.id)}')">
      <div class="crm-inbox-conv-avatar">${name.charAt(0).toUpperCase()}</div>
      <div style="display:flex;flex-direction:column;flex:1;min-width:0">
        <div class="crm-inbox-conv-info">
          <div class="crm-inbox-conv-name">${esc(name)}</div>
          <div class="crm-inbox-conv-preview">${esc((conv.last_message || '').slice(0, 50))}</div>
        </div>
      </div>
      <div class="crm-inbox-conv-meta">
        <div class="crm-inbox-conv-time">${time}</div>
        ${conv.unread_count > 0 ? `<div class="crm-inbox-unread">${conv.unread_count}</div>` : ''}
        <div class="crm-inbox-channel-dot ${conv.channel}" title="${conv.channel}"></div>
      </div>
    </div>`;
  }).join('');
}

async function inboxOpenConv(convId) {
  inboxActiveConvId = convId;
  inboxRenderList();
  const conv = inboxConversations.find(c => c.id === convId);
  if (!conv) return;

  // Mark as read
  if (conv.unread_count > 0) {
    conv.unread_count = 0;
    await fetch('/api/chat-conversations', {
      method: 'PUT',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: convId, unread_count: 0 }),
    });
    inboxUpdateBadge();
  }

  // Load messages
  const res = await fetch(`/api/chat-conversations?messages=${encodeURIComponent(convId)}`, { headers: await getAuthHeaders() });
  if (!res.ok) return;
  const data = await res.json();
  const messages = data.messages || [];

  const name = conv.contact_name || conv.contact_phone || conv.contact_id || 'Desconocido';
  const channelLabels = { messenger: 'Messenger', instagram: 'Instagram', whatsapp: 'WhatsApp', tiktok: 'TikTok' };
  const statusLabels = { bot: 'Bot activo', human: 'Escalado', resolved: 'Resuelto' };

  const chat = document.getElementById('crm-inbox-chat');
  chat.innerHTML = `
    <div class="crm-inbox-chat-head">
      <div style="display:flex;flex-direction:column">
        <div class="crm-inbox-chat-name">${esc(name)}</div>
        <div style="font-size:11px;color:var(--muted)">${esc(channelLabels[conv.channel] || conv.channel)}${conv.lead_id ? ` · <button class="crm-lead-link-btn" onclick="crmOpenDetail('${esc(conv.lead_id)}')"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/></svg> Ver lead</button>` : ''}</div>
      </div>
      <div style="display:flex;align-items:center;gap:8px">
        ${!conv.lead_id ? `<button class="crm-conv-link-btn" style="width:auto;padding:5px 10px;border-style:solid" onclick="crmCreateLeadFromConversation(inboxConversations.find(c=>c.id==='${esc(conv.id)}'))"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg> Crear lead</button>` : ''}
        <button class="crm-inbox-status-btn ${conv.status}" onclick="inboxCycleStatus('${esc(conv.id)}','${esc(conv.status)}')">${esc(statusLabels[conv.status] || conv.status)}</button>
      </div>
    </div>
    <div class="crm-inbox-messages" id="inbox-msgs">
      ${messages.map(m => `
        <div class="crm-inbox-bubble-wrap ${m.role}">
          <div class="crm-inbox-bubble ${m.role}">${esc(m.content.replace(/\[CAPTURA:.*?\]/gs, '').replace(/\[ESCALAR\]/g, '').trim())}</div>
          <div class="crm-inbox-bubble-time">${m.created_at ? new Date(m.created_at).toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' }) : ''}</div>
        </div>`).join('')}
    </div>
    <div class="crm-inbox-reply">
      <textarea class="crm-inbox-reply-input" id="inbox-reply-input" placeholder="Escribe un mensaje manual..." onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();inboxSendManual('${esc(convId)}')}" rows="1"></textarea>
      <button class="crm-inbox-reply-btn" onclick="inboxSendManual('${esc(convId)}')">Enviar</button>
    </div>`;

  // Scroll to bottom
  setTimeout(() => {
    const msgs = document.getElementById('inbox-msgs');
    if (msgs) msgs.scrollTop = msgs.scrollHeight;
  }, 50);
}

async function inboxSendManual(convId) {
  const input = document.getElementById('inbox-reply-input');
  if (!input) return;
  const content = input.value.trim();
  if (!content) return;
  input.value = '';
  const btn = input.nextElementSibling;
  if (btn) btn.disabled = true;
  try {
    await fetch('/api/chat-conversations', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ conversation_id: convId, content }),
    });
    await inboxOpenConv(convId);
  } catch(e) { console.error('inboxSendManual', e); }
  if (btn) btn.disabled = false;
}

async function inboxCycleStatus(convId, current) {
  const next = current === 'bot' ? 'human' : current === 'human' ? 'resolved' : 'bot';
  await fetch('/api/chat-conversations', {
    method: 'PUT',
    headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
    body: JSON.stringify({ id: convId, status: next }),
  });
  const conv = inboxConversations.find(c => c.id === convId);
  if (conv) conv.status = next;
  await inboxOpenConv(convId);
}

function inboxUpdateBadge() {
  const total = inboxConversations.reduce((s, c) => s + (c.unread_count || 0), 0);
  const badge = document.getElementById('crm-inbox-unread-badge');
  if (badge) { badge.style.display = total > 0 ? 'inline-flex' : 'none'; badge.textContent = total; }
}

function timeAgo(iso) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'ahora';
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  return `${Math.floor(h / 24)}d`;
}

function inboxSetFilter(status, btn) {
  document.querySelectorAll('.crm-inbox-filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  crmLoadInbox(status);
}

function crmRenderAnalytics() {
  const container = document.getElementById('crm-analytics-view');
  if (!container) return;
  const now = Date.now();
  const active = crmLeads.filter(l => l.stage !== 'ganado' && l.stage !== 'perdido');
  const won = crmLeads.filter(l => l.stage === 'ganado');
  const total = crmLeads.length;
  const pipelineValue = active.reduce((s, l) => s + (Number(l.value) || 0), 0);
  const wonValue = won.reduce((s, l) => s + (Number(l.value) || 0), 0);
  const avgValue = total > 0 ? Math.round(pipelineValue / Math.max(active.length, 1)) : 0;
  const convRate = total > 0 ? Math.round((won.length / total) * 100) : 0;
  const maxCount = Math.max(...crmStages.map(s => crmLeads.filter(l => l.stage === s.key).length), 1);
  const stageFunnel = crmStages.map(s => {
    const cnt = crmLeads.filter(l => l.stage === s.key).length;
    const val = crmLeads.filter(l => l.stage === s.key).reduce((sum, l) => sum + (Number(l.value) || 0), 0);
    return { label: s.label, color: s.color, key: s.key, count: cnt, value: val, pct: Math.round((cnt / maxCount) * 100) };
  });
  const sourceCounts = {};
  crmLeads.forEach(l => { const s = l.source || 'manual'; sourceCounts[s] = (sourceCounts[s] || 0) + 1; });
  const maxSrc = Math.max(...Object.values(sourceCounts), 1);
  const sourceLabels = { manual: 'Manual', meta_ads: 'Meta Ads', google_ads: 'Google Ads', organico: 'Organico', referido: 'Referido', web: 'Web' };
  const needsAttention = crmLeads.filter(l => {
    if (l.stage === 'ganado' || l.stage === 'perdido') return false;
    const lastActive = l.updated_at ? new Date(l.updated_at).getTime() : new Date(l.created_at || 0).getTime();
    return Math.floor((now - lastActive) / 86400000) >= 7;
  }).sort((a, b) => new Date(a.updated_at || a.created_at) - new Date(b.updated_at || b.created_at)).slice(0, 8);
  // Distribución por etiqueta: conteo + valor de pipeline por tag (top 12)
  const tagStats = {};
  crmLeads.forEach(l => (l.tags || []).forEach(t => {
    if (!tagStats[t]) tagStats[t] = { count: 0, value: 0 };
    tagStats[t].count++;
    tagStats[t].value += Number(l.value) || 0;
  }));
  const tagRows = Object.entries(tagStats).sort((a, b) => b[1].count - a[1].count).slice(0, 12);
  const maxTag = Math.max(...tagRows.map(([, s]) => s.count), 1);
  const tagSection = tagRows.length
    ? '<div class="crm-analytics-section"><div class="crm-analytics-section-title">Leads por etiqueta</div>' +
      tagRows.map(([name, s]) => {
        const c = tagColor(name);
        return '<div class="crm-source-row" style="cursor:pointer" title="Ver estos leads en el pipeline" onclick="crmFilterTags=[\'' + esc(name) + '\'];crmRenderTagFilter();crmSetView(\'kanban\')">' +
          '<div class="crm-source-label"><span class="tag-chip" style="background:' + c + '1A;color:' + c + '">' + (tagIsAuto(name) ? '⚡' : '') + esc(name) + '</span></div>' +
          '<div class="crm-source-bar-wrap"><div class="crm-source-bar" style="width:' + Math.round((s.count / maxTag) * 100) + '%;background:' + c + '"></div></div>' +
          '<div class="crm-source-count">' + s.count + '</div>' +
          '<div class="crm-analytics-stage-val">' + (s.value > 0 ? '$' + s.value.toLocaleString('es-CO') : '') + '</div>' +
        '</div>';
      }).join('') + '</div>'
    : '';
  container.innerHTML = '<div class="crm-analytics-grid"><div class="crm-analytics-card"><div class="crm-analytics-card-title">Total leads</div><div class="crm-analytics-stat">' + total + '</div><div class="crm-analytics-sub">' + active.length + ' activos - ' + won.length + ' ganados</div></div><div class="crm-analytics-card"><div class="crm-analytics-card-title">Pipeline activo</div><div class="crm-analytics-stat" style="font-size:20px">$' + pipelineValue.toLocaleString('es-CO') + '</div><div class="crm-analytics-sub">Valor en proceso</div></div><div class="crm-analytics-card"><div class="crm-analytics-card-title">Deals ganados</div><div class="crm-analytics-stat" style="font-size:20px">$' + wonValue.toLocaleString('es-CO') + '</div><div class="crm-analytics-sub">' + convRate + '% tasa de cierre</div></div><div class="crm-analytics-card"><div class="crm-analytics-card-title">Valor promedio</div><div class="crm-analytics-stat" style="font-size:20px">$' + avgValue.toLocaleString('es-CO') + '</div><div class="crm-analytics-sub">Por deal activo</div></div></div><div class="crm-analytics-section"><div class="crm-analytics-section-title">Embudo del pipeline</div>' + stageFunnel.map(s => '<div class="crm-analytics-stage-row"><div class="crm-analytics-dot" style="background:' + s.color + '"></div><div class="crm-analytics-stage-name">' + esc(s.label) + '</div><div class="crm-analytics-bar-wrap"><div class="crm-analytics-bar" style="width:' + s.pct + '%;background:' + s.color + '"></div></div><div class="crm-analytics-stage-count">' + s.count + '</div><div class="crm-analytics-stage-val">' + (s.value > 0 ? '$' + s.value.toLocaleString('es-CO') : '') + '</div></div>').join('') + '</div>' + (Object.keys(sourceCounts).length > 0 ? '<div class="crm-analytics-section"><div class="crm-analytics-section-title">Fuentes de leads</div>' + Object.entries(sourceCounts).sort((a, b) => b[1] - a[1]).map(([src, cnt]) => '<div class="crm-source-row"><div class="crm-source-label">' + esc(sourceLabels[src] || src) + '</div><div class="crm-source-bar-wrap"><div class="crm-source-bar" style="width:' + Math.round((cnt / maxSrc) * 100) + '%"></div></div><div class="crm-source-count">' + cnt + '</div></div>').join('') + '</div>' : '') + tagSection + (needsAttention.length > 0 ? '<div class="crm-analytics-section"><div class="crm-analytics-section-title" style="color:#D97706">Requieren atencion (' + needsAttention.length + ')</div>' + needsAttention.map(l => { const days = Math.floor((now - new Date(l.updated_at || l.created_at).getTime()) / 86400000); const st = crmStages.find(s => s.key === l.stage) || { label: l.stage, color: 'var(--muted)' }; return '<div class="crm-attention-item" onclick="crmOpenDetail(\'' + esc(l.id) + '\')"><div class="crm-attention-days">' + days + 'd</div><div style="flex:1">' + esc(l.name) + (l.company ? '<span style="color:var(--muted);margin-left:4px">- ' + esc(l.company) + '</span>' : '') + '</div><div class="crm-attention-stage" style="background:' + st.color + '20;color:' + st.color + '">' + esc(st.label) + '</div></div>'; }).join('') + '</div>' : '');
}

function crmCreateLeadFromConversation(conv) {
  if (!conv) return;
  crmEditingId = null;
  document.getElementById('crm-modal-title').textContent = 'Lead desde conversacion';
  document.getElementById('crm-f-name').value = conv.contact_name || '';
  document.getElementById('crm-f-phone').value = conv.contact_phone || '';
  document.getElementById('crm-f-email').value = '';
  document.getElementById('crm-f-company').value = '';
  document.getElementById('crm-f-notes').value = 'Lead capturado desde ' + (conv.channel || 'chat') + '.';
  document.getElementById('crm-f-source').value = conv.channel === 'whatsapp' ? 'web' : (conv.channel === 'meta_ads' ? 'meta_ads' : 'web');
  const valCLEl = document.getElementById('crm-f-value');
  if (valCLEl) valCLEl.value = '';
  const tagsCLEl = document.getElementById('crm-f-tags');
  if (tagsCLEl) tagsCLEl.value = '';
  crmPopulateStageSelects();
  document.getElementById('crm-f-stage').value = 'nuevo';
  document.getElementById('crm-save-btn').disabled = false;
  document.getElementById('crm-modal').classList.add('open');
}

// ── Copiloto IA en panel de detalle ───────────────────────────────────────────
let copilotActiveAction = 'analyze';
let copilotLoading = false;

function crmCopilotToggle() {
  const panel = document.getElementById('crm-copilot-panel');
  const overlay = document.getElementById('crm-copilot-overlay');
  if (!panel || !crmDetailLead) return;
  if (panel.style.display === 'none') {
    panel.style.display = 'block';
    overlay.style.display = 'block';
  } else {
    crmCopilotClose();
  }
}

function crmCopilotClose() {
  const panel = document.getElementById('crm-copilot-panel');
  const overlay = document.getElementById('crm-copilot-overlay');
  if (panel) panel.style.display = 'none';
  if (overlay) overlay.style.display = 'none';
}

async function crmCopilotAction(action, btn) {
  if (copilotLoading || !crmDetailLead) return;
  copilotActiveAction = action;
  document.querySelectorAll('.crm-copilot-tab').forEach(t => t.classList.remove('active'));
  if (btn) btn.classList.add('active');

  copilotLoading = true;
  const content = document.getElementById('crm-copilot-content');
  content.innerHTML = '<div style="text-align:center;padding:20px 0;color:var(--muted);font-size:13px">Analizando con IA...</div>';

  try {
    const res = await fetch('/api/lead-copilot', {
      method: 'POST',
      headers: { ...(await getAuthHeaders()), 'Content-Type': 'application/json' },
      body: JSON.stringify({ lead_id: crmDetailLead.id, action }),
    });
    if (!res.ok) throw new Error();
    const data = await res.json();

    if (action === 'score' && data.score) {
      const s = data.score;
      content.innerHTML = `
        <div class="crm-copilot-panel">
          <div class="crm-copilot-score">
            <div class="crm-score-num">${s.score}</div>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:700;color:#7C3AED;margin-bottom:5px">Prob. de cierre: ${esc(s.label || '')}</div>
              <div class="crm-score-bar-wrap"><div class="crm-score-bar" style="width:${s.score * 10}%"></div></div>
            </div>
          </div>
          <div style="font-size:12px;color:var(--text);line-height:1.5">${esc(s.reason || '')}</div>
          ${s.days_estimate ? `<div style="font-size:11px;color:var(--muted)">Estimado de cierre: ~${s.days_estimate} días</div>` : ''}
        </div>`;
    } else if (action === 'draft_message' && data.result) {
      content.innerHTML = `
        <div class="crm-copilot-panel">
          <div class="crm-copilot-result">${esc(data.result)}</div>
          <button class="crm-copy-msg-btn" onclick="navigator.clipboard.writeText(${JSON.stringify(data.result)}).then(()=>{this.textContent='✓ Copiado'})">Copiar mensaje</button>
        </div>`;
    } else if (data.result) {
      content.innerHTML = `<div class="crm-copilot-panel"><div class="crm-copilot-result">${data.result.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')}</div></div>`;
    }
  } catch(e) {
    content.innerHTML = '<div style="color:#EF4444;font-size:12px;padding:10px 0">Error al consultar la IA. Intenta de nuevo.</div>';
  }
  copilotLoading = false;
}

// crmInit — carga stages + leads + agents en paralelo y renderiza al final
async function crmInit() {
  if (crmInited) { crmRender(); return; }
  crmInited = true;
  await Promise.all([crmLoadStages(), crmLoadLeads(), crmLoadAgents(), crmLoadTags()]);
  crmRender(); // garantiza render con todos los datos cargados
  crmRenderTagFilter();
  crmLoadInbox();
  crmUpdateSidebarCount();
}

